  /// Adds a planned line: `amount` cents, due as `repeat` says from
  /// `first` (`2026-11-05`) on.
  Future<String> addLine({
    required String budget,
    required String name,
    required String category,
    required bool income,
    required PlatformInt64 amount,
    required Repeat repeat,
    required String first,
  }) => RustLib.instance.api.crateApiAppAddLine(
    that: this,
    budget: budget,
    name: name,
    category: category,
    income: income,
    amount: amount,
    repeat: repeat,
    first: first,
  );

  /// Adds a transaction of `amount` cents on `date`, realising the line
  /// `line` (its identifier) if given.
  Future<String> addTransaction({
    required String budget,
    required String dateText,
    required bool income,
    required PlatformInt64 amount,
    required String category,
    String? line,
    required String note,
  }) => RustLib.instance.api.crateApiAppAddTransaction(
    that: this,
    budget: budget,
    dateText: dateText,
    income: income,
    amount: amount,
    category: category,
    line: line,
    note: note,
  );

  /// The budgets, by name, with this month's balances.
  Future<List<BudgetSummary>> budgets() =>
      RustLib.instance.api.crateApiAppBudgets(that: this);

  /// The twelve months of `year` for budget `budget`.
  Future<List<MonthCell>> calendar({
    required String budget,
    required int year,
  }) => RustLib.instance.api.crateApiAppCalendar(
    that: this,
    budget: budget,
    year: year,
  );

  /// Creates a budget; returns its identifier.
  Future<String> createBudget({
    required String name,
    required String currency,
  }) => RustLib.instance.api.crateApiAppCreateBudget(
    that: this,
    name: name,
    currency: currency,
  );

  /// Month `month` (`2026-11`) of budget `budget`.
  Future<MonthView> month({required String budget, required String month}) =>
      RustLib.instance.api.crateApiAppMonth(
        that: this,
        budget: budget,
        month: month,
      );
